<script lang="ts">import {colors} from '../charts';let {seconds}:{seconds:number[]}=$props();let total=$derived(seconds.reduce((a,b)=>a+b,0));</script><div class="zbar" aria-label="Time in heart-rate zones">{#each seconds as s,i}<i style:width={(total?s/total*100:0)+'%'} style:background={colors.z[i]??colors.poor}></i>{/each}</div><style>.zbar{display:flex;height:8px;border-radius:4px;overflow:hidden;gap:2px;margin-top:14px}i{display:block;height:100%}</style>